let questions = [];
const levels = ["سهل","متوسط","متقدم"];

let index=0, earned=0, used={fifty:false,audience:false,friend:false}, locked=false, soundOn=true;
const $ = id => document.getElementById(id);
const letters=["أ","ب","ج","د"];
const screens=["start-screen","game-screen","end-screen"];
function shuffle(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function chooseQuestions(){
 const easy=shuffle(questionBank.filter(q=>q.level==="سهل"));
 const medium=shuffle(questionBank.filter(q=>q.level==="متوسط"));
 const hard=shuffle(questionBank.filter(q=>q.level==="متقدم"));
 // تدرّج متوازن: 4 سهلة، 6 متوسطة، 5 متقدمة.
 let selected=[...easy.slice(0,4),...medium.slice(0,6),...hard.slice(0,5)];
 // نخلط الخيارات داخل كل سؤال مع تحديث موضع الإجابة الصحيحة.
 selected=selected.map(q=>{const order=shuffle([0,1,2,3]);return {...q,a:order.map(i=>q.a[i]),c:order.indexOf(q.c)};});
 // نحتفظ بمعرّفات الجولة السابقة لتقليل تكرار نفس الأسئلة في الجولة التالية.
 try{
  const previous=JSON.parse(localStorage.getItem("millionLastQuestionIds")||"[]");
  if(selected.some(q=>previous.includes(q.id))){
   const alternatives=shuffle(questionBank.filter(q=>!selected.some(s=>s.id===q.id)&&!previous.includes(q.id)));
   for(let i=0;i<selected.length&&alternatives.length;i++){
    if(previous.includes(selected[i].id)){
     const replacement=alternatives.find(q=>q.level===selected[i].level);
     if(replacement){const pos=alternatives.indexOf(replacement);alternatives.splice(pos,1);const order=shuffle([0,1,2,3]);selected[i]={...replacement,a:order.map(k=>replacement.a[k]),c:order.indexOf(replacement.c)};}
    }
   }
  }
  localStorage.setItem("millionLastQuestionIds",JSON.stringify(selected.map(q=>q.id)));
 }catch(e){}
 return selected;
}
function showScreen(id){screens.forEach(s=>$(s).classList.toggle("hidden",s!==id));}
function format(n){return n.toLocaleString("en-US");}
function renderLadder(){
 const list=$("prize-ladder");list.innerHTML="";
 [...prizes].reverse().forEach((p,rev)=>{const i=14-rev,li=document.createElement("li");li.textContent=format(p);if(i===index)li.classList.add("active");if(i===4||i===9)li.classList.add("safe");list.appendChild(li);});
}
function renderQuestion(){
 locked=false;const item=questions[index];
 $("question-number").textContent=index+1;$("current-prize").textContent=format(earned);
 $("question-text").textContent=item.q;
 const level=$("question-level");if(level)level.textContent="مستوى الصعوبة: "+item.level;
 $("feedback").textContent="";$("feedback").className="feedback";$("next-button").classList.add("hidden");$("answers").innerHTML="";
 item.a.forEach((answer,i)=>{const btn=document.createElement("button");btn.type="button";btn.className="answer";btn.dataset.index=i;btn.innerHTML=`<span class="letter">${letters[i]}:</span><span></span>`;btn.querySelector("span:last-child").textContent=answer;btn.addEventListener("click",()=>chooseAnswer(i));$("answers").appendChild(btn);});
 $("fifty-button").disabled=used.fifty;$("audience-button").disabled=used.audience;$("friend-button").disabled=used.friend;renderLadder();
}
function playTone(freq=660,duration=.12){if(!soundOn)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)();const osc=ctx.createOscillator(),gain=ctx.createGain();osc.connect(gain);gain.connect(ctx.destination);osc.frequency.value=freq;gain.gain.value=.045;osc.start();gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);osc.stop(ctx.currentTime+duration);}catch(e){}}
function chooseAnswer(choice){
 if(locked)return;locked=true;const correct=questions[index].c;
 [...$("answers").children].forEach((b,i)=>{b.disabled=true;if(i===correct)b.classList.add("correct");if(i===choice&&choice!==correct)b.classList.add("wrong");});
 if(choice===correct){earned=prizes[index];$("feedback").textContent="إجابة صحيحة! أحسنت 🎉";$("feedback").className="feedback good";playTone(880,.2);$("current-prize").textContent=format(earned);if(index===14)setTimeout(()=>endGame(true),900);else $("next-button").classList.remove("hidden");}
 else{$("feedback").textContent="للأسف، الإجابة غير صحيحة."; $("feedback").className="feedback bad";playTone(180,.3);setTimeout(()=>endGame(false),1200);}
}
function endGame(won){showScreen("end-screen");$("final-prize").textContent=format(earned);$("end-icon").textContent=won?"🏆":"💡";$("end-eyebrow").textContent=won?"مبروك!":"انتهت الجولة";$("end-title").textContent=won?"أصبحت بطل تحدّي المليون!":"إجابة غير صحيحة";$("end-message").textContent=won?"أجبت عن الأسئلة الخمسة عشر كلها بنجاح.":"رصيدك الافتراضي هو "+format(earned)+". يمكنك المحاولة مرة أخرى وتحقيق نتيجة أفضل.";}
function openModal(title,html){$("modal-title").textContent=title;$("modal-content").innerHTML=html;$("modal").classList.remove("hidden");}
function closeModal(){$("modal").classList.add("hidden");}
function useFifty(){if(used.fifty||locked)return;used.fifty=true;$("fifty-button").disabled=true;const correct=questions[index].c,wrong=shuffle([0,1,2,3].filter(x=>x!==correct)).slice(0,2);wrong.forEach(i=>{const b=$("answers").querySelector(`[data-index="${i}"]`);b.disabled=true;b.classList.add("hidden");});}
function useAudience(){if(used.audience||locked)return;used.audience=true;$("audience-button").disabled=true;const correct=questions[index].c;let vals=[0,0,0,0],remain=60+Math.floor(Math.random()*26);vals[correct]=remain;let others=shuffle([0,1,2,3].filter(x=>x!==correct)),left=100-remain;others.forEach((v,i)=>{vals[v]=i===2?left:Math.floor(left/3);left-=vals[v];});const bars=vals.map((v,i)=>`<div class="bar-wrap"><strong>${v}%</strong><div class="bar" style="height:${v}px"></div><small>${letters[i]}</small></div>`).join("");openModal("نتيجة تصويت الجمهور",`<p>هذه تقديرات الجمهور، وليست ضماناً للإجابة الصحيحة.</p><div class="bars">${bars}</div>`);}
function useFriend(){if(used.friend||locked)return;used.friend=true;$("friend-button").disabled=true;const correct=questions[index].c,confident=Math.random()<.78,guess=confident?correct:shuffle([0,1,2,3].filter(x=>x!==correct))[0];openModal("الاتصال بصديق",`<p>📞 صديقك يقول:</p><p><strong>«أعتقد أن الإجابة هي ${letters[guess]}: ${questions[index].a[guess]}${confident?"، وأنا واثق إلى حد كبير.":"، لكنني لست متأكداً تماماً."}»</strong></p>`);}
function newGame(){index=0;earned=0;used={fifty:false,audience:false,friend:false};questions=chooseQuestions();showScreen("game-screen");renderQuestion();}
$("start-button").addEventListener("click",newGame);
$("next-button").addEventListener("click",()=>{index++;renderQuestion();});
$("restart-button").addEventListener("click",newGame);
$("fifty-button").addEventListener("click",useFifty);$("audience-button").addEventListener("click",useAudience);$("friend-button").addEventListener("click",useFriend);
$("modal-close").addEventListener("click",closeModal);$("modal-ok").addEventListener("click",closeModal);$("modal").addEventListener("click",e=>{if(e.target===$("modal"))closeModal();});
$("sound-toggle").addEventListener("click",()=>{soundOn=!soundOn;$("sound-toggle").textContent=soundOn?"🔊":"🔇";});
